// Solara: Last Light — a sun-soaked coastal open-world adventure.
import{TIME,SPAWN}from'./config.js';import{generateCity}from'./city.js';import{Player,moveOnFoot,driveVehicle,enterExitVehicle,addCash}from'./player.js';import{parkedCars,updateTraffic}from'./vehicles.js';import{spawnPedestrians,walkSidewalks,panic}from'./pedestrians.js';import{WantedSystem,updateChase}from'./police.js';import{Weapon,firePistol,updateBullets}from'./combat.js';import{MissionRunner}from'./missions.js';import{Activities}from'./activities.js';import{Wallet}from'./economy.js';import{Renderer}from'./render.js';import{Menu}from'./menu.js';import{AudioEngine}from'./audio.js';import{Particles}from'./effects.js';import{saveGame,loadGame}from'./save.js';import{applyShot}from'./shots.js';import{RADIO_STATIONS,MISSIONS}from'./story.js';
export function boot(){const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),status=document.querySelector('#status'),renderer=new Renderer(canvas,ctx),params=new URLSearchParams(location.search),seed=Number(params.get('seed'))||1;let scene='title',last=0,acc=0,keys={},mouse={x:640,y:360},lastStep=0;const city=generateCity(seed),player=new Player(),mission=new MissionRunner(),wanted=new WantedSystem(),weapon=new Weapon(),menu=new Menu(),audio=new AudioEngine(),effects=new Particles(),activities=new Activities(),cars=parkedCars(city,seed),people=spawnPedestrians(64,seed),wallet=new Wallet(player.cash);Object.assign(player,loadGame()||{});const state={scene,city,player,mission,wanted,weapon,menu,audio,effects,activities,cars,people,objective:MISSIONS[0].objective,radio:RADIO_STATIONS[0],camera:{x:SPAWN.x,y:SPAWN.y,z:140,angle:SPAWN.angle},message:'',};const input={};const shot=params.get('shot');if(shot){applyShot(shot,state);scene=state.scene;mission.active=true;for(let i=0;i<180;i++)step(1/60,true);render();requestAnimationFrame(()=>{render();window.__shotReady=true;});return;}
function setKey(e,value){keys[e.code]=value;input.up=keys.KeyW||keys.ArrowUp;input.down=keys.KeyS||keys.ArrowDown;input.left=keys.KeyA||keys.ArrowLeft;input.right=keys.KeyD||keys.ArrowRight;input.sprint=keys.ShiftLeft||keys.ShiftRight;}
window.addEventListener('keydown',e=>{setKey(e,true);audio.unlock();if(['Space','Tab','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(e.repeat)return;if(scene==='title'){scene='play';state.scene=scene;mission.startMission();return;}if(e.code==='KeyP'||e.code==='Tab'){scene=scene==='paused'?'play':'paused';state.scene=scene;}if(e.code==='KeyM'){state.mapOpen=!state.mapOpen;}if(e.code==='KeyE'&&scene==='play')enterExitVehicle(player,cars);if(e.code==='Space'&&scene==='play')firePistol(weapon,player,people);if(e.code==='KeyJ'){mission.startMission();scene='mission';state.scene=scene;}if(e.code==='Escape'&&scene==='mission'){scene='play';state.scene=scene;}if(e.code==='Digit1')activities.streetRace(activities,player,1/60);if(e.code==='Digit2')activities.deliveryRun(activities,player,1/60);if(e.code==='Digit3')activities.rampage(activities,player,1/60);if(scene==='failed'&&e.code==='Enter'){player.health=100;mission.retryMission();scene='play';state.scene=scene;}});window.addEventListener('keyup',e=>setKey(e,false));canvas.addEventListener('mousemove',e=>{const r=canvas.getBoundingClientRect();mouse.x=(e.clientX-r.left)*1280/r.width;mouse.y=(e.clientY-r.top)*720/r.height;});canvas.addEventListener('mousedown',e=>{audio.unlock();if(scene==='title'){scene='play';state.scene=scene;mission.startMission();}else if(scene==='play'&&e.button===0)firePistol(weapon,player,people);});
function step(dt,harmless=false){if(scene==='play'||scene==='mission'){if(player.vehicle)driveVehicle(player,input,dt,city);else moveOnFoot(player,input,dt,city);if(keys.MouseLook)player.angle=Math.atan2(mouse.y-360,mouse.x-640);walkSidewalks(people,dt,city);updateTraffic(cars,dt,city);updateChase(wanted,player,cars,dt);updateBullets(weapon,dt);mission.updateObjectives(player,dt);if(mission.complete){addCash(player,mission.current().reward);state.message=mission.message;mission.complete=false;mission.startMission(mission.index);}if(!harmless&&weapon.cooldown===0&&keys.Fire)firePistol(weapon,player,people);if(!harmless&&player.vehicle&&Math.abs(player.vehicle.speed)>260)effects.dust(player.x,player.y);effects.update(dt);const target=player.vehicle||player;state.camera.x+=(target.x-Math.cos(target.angle)*310-state.camera.x)*.08;state.camera.y+=(target.y-Math.sin(target.angle)*310-state.camera.y)*.08;state.camera.angle=target.angle;if(player.health<=0){scene='failed';state.scene=scene;}if(Math.floor(performance.now()/1000)!==lastStep){lastStep=Math.floor(performance.now()/1000);saveGame(state);}}menu.update(dt);}
function render(){state.scene=scene;state.wanted=wanted;state.menu=menu;state.effects=effects;state.people=people;state.cars=cars;state.mission=mission;state.objective=mission.active?mission.current().objective:MISSIONS[mission.index]?.objective||'Explore Solara Bay';state.message=mission.active?'':state.message;renderer.draw(state);if(scene==='failed'){ctx.fillStyle='#112735cc';ctx.fillRect(0,0,1280,720);ctx.textAlign='center';ctx.fillStyle='#fff0cc';ctx.font='bold 54px system-ui';ctx.fillText('SIGNAL LOST',640,330);ctx.font='18px system-ui';ctx.fillText('ENTER TO GET BACK IN THE DRIVER’S SEAT',640,380);}if(state.mapOpen){ctx.fillStyle='#112735dd';ctx.fillRect(180,70,920,580);ctx.fillStyle='#fff';ctx.textAlign='center';ctx.font='bold 24px system-ui';ctx.fillText('SOLARA BAY — FIELD MAP',640,115);ctx.strokeStyle='#afc8ba';ctx.lineWidth=8;for(let x=250;x<1060;x+=90){ctx.beginPath();ctx.moveTo(x,150);ctx.lineTo(x,600);ctx.stroke();}for(let y=180;y<610;y+=90){ctx.beginPath();ctx.moveTo(220,y);ctx.lineTo(1060,y);ctx.stroke();}ctx.fillStyle='#ffd36f';ctx.beginPath();ctx.arc(600+(player.x%500),350+(player.y%210),9,0,Math.PI*2);ctx.fill();}}
function frame(now){if(!last)last=now;const delta=Math.min(TIME.maxFrame,(now-last)/1000);last=now;acc+=delta;while(acc>=TIME.step){step(TIME.step);acc-=TIME.step;}render();requestAnimationFrame(frame);}function stepForShot(dt){step(dt,true);}requestAnimationFrame(frame);return{state,step:stepForShot,render};}
boot();
