import{SPAWN,SPEED,HANDLING}from'./config.js';import{clamp}from'./math3d.js';import{stealVehicle}from'./vehicles.js';
export class Player{constructor(){Object.assign(this,{x:SPAWN.x,y:SPAWN.y,angle:SPAWN.angle,health:100,armor:20,cash:1250,vehicle:null,ammo:48,score:0});}}
export function moveOnFoot(player,input,dt,city){let dx=(input.right?1:0)-(input.left?1:0),dy=(input.down?1:0)-(input.up?1:0);if(dx||dy){const n=Math.hypot(dx,dy),speed=input.sprint?SPEED.sprint:SPEED.walk;dx=dx/n*speed*dt;dy=dy/n*speed*dt;player.angle=Math.atan2(dy,dx);}if(!city.collides(player.x+dx,player.y,14))player.x+=dx;if(!city.collides(player.x,player.y+dy,14))player.y+=dy;}
export function driveVehicle(player,input,dt,city){const car=player.vehicle;if(!car)return;const accel=(input.up?1:0)-(input.down?1:0);car.speed=clamp(car.speed+accel*(accel<0?SPEED.reverse:SPEED.car)*dt,-120,SPEED.car);car.speed*=Math.pow(.985,dt*60);const steer=(input.right?1:0)-(input.left?1:0);car.angle+=steer*HANDLING.turn*(.25+Math.abs(car.speed)/SPEED.car)*dt*Math.sign(car.speed||1)*car.model.handling;const nx=car.x+Math.cos(car.angle)*car.speed*dt,ny=car.y+Math.sin(car.angle)*car.speed*dt;if(city.collides(nx,ny,25)){car.speed*=-.3;player.health=Math.max(1,player.health-1);}else{car.x=nx;car.y=ny;}player.x=car.x;player.y=car.y;player.angle=car.angle;}
export function enterExitVehicle(player,cars){if(player.vehicle){const c=player.vehicle;c.occupied=false;player.x=c.x-Math.sin(c.angle)*42;player.y=c.y+Math.cos(c.angle)*42;player.vehicle=null;return false;}return Boolean(stealVehicle(player,cars));}
export function applyCollision(player,other,damage=10){if(Math.hypot(player.x-other.x,player.y-other.y)<48){player.health=Math.max(0,player.health-damage);if(player.vehicle)player.vehicle.speed*=-.4;return true;}return false;}
export function damage(player,amount){player.health=Math.max(0,player.health-amount);return player.health===0;}
export function addCash(player,amount){player.cash=Math.max(0,player.cash+amount);}
