import{seedRandom,choose,range}from'./noise.js';
export const CAR_MODELS=[{name:'Mistral GT',color:'#f07c56',speed:420,handling:1.1},{name:'Citrus Cab',color:'#eac85e',speed:310,handling:.88},{name:'Bluefin Coupe',color:'#53aeb0',speed:380,handling:1.03},{name:'Nightjar Sedan',color:'#384e64',speed:340,handling:.92},{name:'Pearl Runner',color:'#e6e2d5',speed:360,handling:1}];
export class Vehicle{constructor(x,y,model=CAR_MODELS[0],angle=0){Object.assign(this,{x,y,model,angle,speed:0,health:100,occupied:false,stolen:false,lights:false,flash:0});this.color=model.color;this.name=model.name;this.w=58;this.h=30;}}
export function parkedCars(city,seed=1,count=42){const rnd=seedRandom(seed+92),cars=[];for(let i=0;i<count;i++){const x=80+Math.floor(rnd()*8)*220,y=60+Math.floor(rnd()*7)*220;cars.push(new Vehicle(x,y,choose(rnd,CAR_MODELS),rnd()<.5?0:Math.PI/2));}return cars;}
export function updateTraffic(cars,dt,city){for(const c of cars){if(c.occupied)continue;c.x+=Math.cos(c.angle)*(c.speed||range(()=>.5,28,62))*dt;c.y+=Math.sin(c.angle)*(c.speed||34)*dt;if(c.x<20||c.x>1880)c.angle=Math.PI-c.angle;if(city.collides(c.x,c.y,22))c.angle+=Math.PI/2;c.flash=(c.flash+dt)%1.2;}}
export function stealVehicle(player,cars){const car=cars.filter(c=>!c.occupied).sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y))[0];if(!car||Math.hypot(car.x-player.x,car.y-player.y)>100)return null;car.occupied=true;car.stolen=true;player.vehicle=car;return car;}
